-- Dabab: preserve the existing Bar catalog and add two independent coffee menus
-- Reviewed source SHA256: c4ba9f978e6d79195a3661e1ba53adaf24d041a867b378f1451bf6005ce6b39f
-- No brand identity, customer, loyalty, subscription, finance or wallet changes
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
LOCK TABLE public.branches,public.menu_categories,public.menu_products IN SHARE ROW EXCLUSIVE MODE;
DO $scope$ BEGIN
 PERFORM 1 FROM public.cafes WHERE id='3813425d-db13-4d30-8b82-9d41aad12e36' AND slug='brand-8ad185ee82e3' AND name='ضباب' AND status='active' AND is_public AND deleted_at IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Dabab identity changed';END IF;
 IF NOT COALESCE(platform_access_private.service_enabled('3813425d-db13-4d30-8b82-9d41aad12e36','menu'),false) THEN RAISE EXCEPTION 'Menu service unavailable';END IF;
 IF EXISTS(SELECT 1 FROM public.branches WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') THEN RAISE EXCEPTION 'Dabab branches changed since review';END IF;
 IF(SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY id)::text,'')) FROM public.menu_products p WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') IS DISTINCT FROM '56b1be4226a7696ae6acd7c684878003' OR(SELECT md5(coalesce(jsonb_agg(to_jsonb(c) ORDER BY id)::text,'')) FROM public.menu_categories c WHERE cafe_id='3813425d-db13-4d30-8b82-9d41aad12e36') IS DISTINCT FROM 'f3148cbfd7fc6c2ecb98d6006c9edd2d' THEN RAISE EXCEPTION 'Bar catalog changed since review';END IF;
 IF(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE conrelid IN('public.branches'::regclass,'public.menu_products'::regclass,'public.menu_categories'::regclass)) IS DISTINCT FROM '[{"definition":"FOREIGN KEY (cafe_id) REFERENCES cafes(id) ON DELETE CASCADE","name":"branches_cafe_id_fkey","table":"branches"},{"definition":"CHECK (((geofence_radius_m >= 10) AND (geofence_radius_m <= 500)))","name":"branches_geofence_radius_m_check","table":"branches"},{"definition":"UNIQUE (id, cafe_id)","name":"branches_id_cafe_unique","table":"branches"},{"definition":"CHECK (((menu_slug IS NULL) OR ((length(menu_slug) <= 80) AND (menu_slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''::text))))","name":"branches_menu_slug_format","table":"branches"},{"definition":"UNIQUE (cafe_id, menu_slug)","name":"branches_menu_slug_unique","table":"branches"},{"definition":"PRIMARY KEY (id)","name":"branches_pkey","table":"branches"},{"definition":"UNIQUE NULLS NOT DISTINCT (cafe_id, branch_id, name)","name":"menu_categories_branch_name_unique","table":"menu_categories"},{"definition":"FOREIGN KEY (branch_id, cafe_id) REFERENCES branches(id, cafe_id)","name":"menu_categories_branch_same_cafe","table":"menu_categories"},{"definition":"FOREIGN KEY (cafe_id) REFERENCES cafes(id) ON DELETE CASCADE","name":"menu_categories_cafe_id_fkey","table":"menu_categories"},{"definition":"PRIMARY KEY (id)","name":"menu_categories_pkey","table":"menu_categories"},{"definition":"CHECK (((cardinality(price_options) <= 10) AND ((0)::numeric <= ALL (price_options)) AND (array_position(price_options, NULL::numeric) IS NULL)))","name":"menu_price_options_valid","table":"menu_products"},{"definition":"FOREIGN KEY (branch_id, cafe_id) REFERENCES branches(id, cafe_id)","name":"menu_products_branch_same_cafe","table":"menu_products"},{"definition":"FOREIGN KEY (cafe_id) REFERENCES cafes(id) ON DELETE CASCADE","name":"menu_products_cafe_id_fkey","table":"menu_products"},{"definition":"CHECK ((catalog_kind = ANY (ARRAY[''product''::text, ''service''::text])))","name":"menu_products_catalog_kind_check","table":"menu_products"},{"definition":"FOREIGN KEY (category_id) REFERENCES menu_categories(id) ON DELETE SET NULL","name":"menu_products_category_id_fkey","table":"menu_products"},{"definition":"CHECK (((jsonb_typeof(commerce_details) = ''object''::text) AND (octet_length((commerce_details)::text) <= 100000)))","name":"menu_products_commerce_details_check","table":"menu_products"},{"definition":"FOREIGN KEY (created_by) REFERENCES profiles(id)","name":"menu_products_created_by_fkey","table":"menu_products"},{"definition":"PRIMARY KEY (id)","name":"menu_products_pkey","table":"menu_products"},{"definition":"CHECK ((price >= (0)::numeric))","name":"menu_products_price_check","table":"menu_products"},{"definition":"FOREIGN KEY (updated_by) REFERENCES profiles(id)","name":"menu_products_updated_by_fkey","table":"menu_products"}]'::jsonb THEN RAISE EXCEPTION 'Catalog constraints changed since review';END IF;
END $scope$;
DO $trigger$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.menu_categories'::regclass AND tgname='menu_category_branch_move' AND tgenabled='O' AND md5(pg_get_functiondef(tgfoid))='22d3cb2a4b55487f81f397aa8d6f4cd1') THEN RAISE EXCEPTION 'Branch guard changed since review';END IF;END $trigger$;
DO $trigger$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.menu_products'::regclass AND tgname='menu_product_branch_category' AND tgenabled='O' AND md5(pg_get_functiondef(tgfoid))='af6d044d3e3ed7ab92ce7ef07da6efcd') THEN RAISE EXCEPTION 'Branch guard changed since review';END IF;END $trigger$;
